function metadata(data) {
  try {
    const m=JSON.parse(data);
    if(!m||Array.isArray(m)||typeof m!=='object'||(m.v!==undefined&&m.v!==1))return null;
    const out={};
    for(const [key,limit] of Object.entries({scene:160,time:80,speaker:80,focus:80,jp:4000}))
      if(typeof m[key]==='string'&&m[key].length<=limit&&!/[<>\r\n]/.test(m[key]))out[key]=m[key];
    if(m.sprites&&typeof m.sprites==='object'&&!Array.isArray(m.sprites)){out.sprites={};for(const [name,value] of Object.entries(m.sprites).slice(0,5))if(name.length<=80&&typeof value==='string'&&value.length<=80&&!/[<>\r\n]/.test(name+value))out.sprites[name]=value;}
    if(Array.isArray(m.present))out.present=m.present.filter(n=>typeof n==='string'&&n.length<=80&&!/[<>\r\n]/.test(n)).slice(0,5);
    if(['day','night','unknown'].includes(m.lighting))out.lighting=m.lighting;
    if(['narrator','dialog','message'].includes(m.type))out.type=m.type;
    return Object.keys(out).length?out:null;
  } catch(_){return null;}
}

function namedDialogue(value){return String(value).trim().match(/^([^\s「」【】<>:：\n]{1,40}(?: [^\s「」【】<>:：\n]{1,40})?)\s*(?:【([^】\n]{1,200})】\s*)?「([^\n]*)」$/u);}
function presentationBlocks(body) {
  const parts=body.split(/(<!--shiomi-vn\b[\s\S]*?-->)/gi), blocks=[];
  let next={}, hasMetadata=false;
  for(const part of parts) {
    if(/^<!--shiomi-vn\b/i.test(part)) {
      const m=metadata(part.replace(/^<!--shiomi-vn\s*/i,'').replace(/-->$/,''));
       
      if(m){next={...next,...m};hasMetadata=true;}
      continue;
    }
    const text=part.replace(/<!--shiomi-vn\b[\s\S]*$/gi,'');
    const paragraphs=text.split(/(<xun_message\b[^>]*>[\s\S]*?<\/xun_message>)/gi)
      .flatMap(p=>/^<xun_message\b/i.test(p)?[p]:p.split(/\n\s*\n/));
    for(const paragraph of paragraphs) {
      if(!paragraph.trim())continue;
      const spans=[];let prose=[];
      for(const row of paragraph.split('\n')){
        if(namedDialogue(row)){
          if(prose.join('\n').trim())spans.push(prose.join('\n').trim());
          prose=[];spans.push(row.trim());
        }else prose.push(row);
      }
      if(prose.join('\n').trim())spans.push(prose.join('\n').trim());
      for(const span of spans){blocks.push({text:span,meta:next});next={};}
    }
  }
  return {blocks,hasMetadata};
}

function createPresentationInjection({inject,remove,isActive,onError=()=>{}}) {
  const id='shiomi-vn-presentation-v1';
  let undo=null;
  function clear(){
    try{if(undo)undo();}catch(e){onError(e);}finally{undo=null;}
    try{remove?.([id]);}catch(e){onError(e);}
  }
  return {
    available:typeof inject==='function'&&typeof remove==='function',
    clear,
    beforeGenerate(){
      clear();
      if(!isActive()||typeof inject!=='function'||typeof remove!=='function')return;
      try{
        const result=inject([{id,position:'in_chat',depth:0,role:'system',content:VN_PROMPT,
          should_scan:false,filter:isActive}],{once:true});
        undo=typeof result?.uninject==='function'?result.uninject:null;
      }catch(e){clear();onError(e);}
    }
  };
}

   
