function commonSceneWords(value){return String(value||'').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');}
function sceneLighting(line){
  if(['day','night','unknown'].includes(line?.lighting))return line.lighting;
  const time=String(line?.time||'');
  if(/夜|凌晨|晚间|晚上/.test(time))return 'night';
  if(/白天|日间|上午|午后|下午|正午|午间/.test(time))return 'day';
  const clock=time.match(/(?:^|\D)(\d{1,2}):(\d{2})(?!\d)/);
  if(clock&&Number(clock[1])<24&&Number(clock[2])<60)return Number(clock[1])>=7&&Number(clock[1])<18?'day':'night';
  return 'unknown';
}
function commonSceneFor(line){
  const target=commonSceneWords(line?.scene);
  if(!target)return null;
  // Exact aliases only: a named shop's back room or a mooring work zone is not a public hall.
  const exact=COMMON_SCENES.find(s=>s.aliases.some(a=>(commonSceneWords(a)===target||sceneTarget(a)===sceneTarget(line?.scene)||s.scene_id===line?.scene)));
  if(exact)return exact;
  return COMMON_SCENES.find(s=>s.aliases.filter(a=>commonSceneWords(a).length>=4).some(a=>{const key=commonSceneWords(a),at=target.indexOf(key);if(at<0)return false;const rest=target.slice(at+key.length);return !rest||/^(?:附近|一带|中央|中部|里面|内部|入口处|空间|区域|营业区|生活巷道|店内)$/.test(rest);}))||null;
}
function commonSceneSelection(line){
  const scene=commonSceneFor(line),lighting=sceneLighting(line);
  const pick=mode=>scene?.assets.find(a=>a.render_mode===mode&&a.lighting===lighting)||scene?.assets.find(a=>a.render_mode===mode)||null;
  const bg=pick('background_with_sprites'),cg=pick('standalone');
  return {scene,bg,cg,approximate:!!bg&&bg.lighting!==lighting};
}
function commonSceneSources(asset){
  if(!asset||!/^(?:backgrounds|standalone)\/[a-z0-9_]+\.png$/.test(asset.file))return [];
  const path=COMMON_SCENE_ROOT+asset.file;
  return ['https://cdn.jsdelivr.net/gh/dongyue233/shiomi@'+COMMON_SCENE_COMMIT+'/'+path,
    'https://raw.githubusercontent.com/dongyue233/shiomi/'+COMMON_SCENE_COMMIT+'/'+path];
}


