  function destroy(){if(dead)return;dead=true;close();releaseMedia();host.clearTimeout(refreshTimer);host.clearTimeout(pendingTimer);chatObserver?.disconnect();stopObserver?.disconnect();for(const f of [...eventDisposers.splice(0),...disposers.splice(0)]){try{f();}catch(_){}}sessions.clear();positions.clear();node.remove();if(host[KEY]===api)delete host[KEY];}
