  function bindHost(ctx){
    const events={...(host.tavern_events||{}),...(local.tavern_events||{}),...(ctx?.event_types||{}),...(ctx?.eventTypes||{})};
    const helperEvents=local.iframe_events||{};
    const signature=JSON.stringify([events,helperEvents]);
    if(signature===eventSignature&&eventBus===ctx?.eventSource&&eventOnOwner===local.eventOn)return;
    for(const off of eventDisposers.splice(0)){try{off();}catch(_){}}
    eventSignature=signature;eventBus=ctx?.eventSource;eventOnOwner=local.eventOn;
    function listen(name,handler){
      if(!name)return false;
      try{
        if(typeof local.eventOn==='function'){
          const off=local.eventOn(name,handler);
          eventDisposers.push(typeof off==='function'?off:typeof off?.stop==='function'?()=>off.stop():()=>local.eventOff?.(name,handler));
          return true;
        }
        const bus=ctx?.eventSource;
        if(bus?.on){bus.on(name,handler);eventDisposers.push(()=>{if(typeof bus.removeListener==='function')bus.removeListener(name,handler);else bus.off?.(name,handler);});return true;}
      }catch(e){console.warn('[ShiomiVN event]',name,e);}
      return false;
    }
    listen('shiomi:xun:updated',queue);listen('shiomi:xun:core-ready',()=>{portraitXunApi=null;queue();});listen('shiomi:xun:core-gone',()=>{portraitXunApi=null;queue();});
    for(const name of ['mag_variable_update_ended','mag_variable_initiailized'])listen(name,queue);
    const portraitRefresh=()=>{castKey='';if(opened)render();};host.addEventListener('shiomi:portraits-updated',portraitRefresh);eventDisposers.push(()=>host.removeEventListener('shiomi:portraits-updated',portraitRefresh));
    const presentationReady=injection.available&&listen(events.GENERATION_AFTER_COMMANDS,()=>injection.beforeGenerate());
    $('.protocol-status').textContent=presentationReady?'阅读界面打开时，为下一次回复启用演出标注；返回普通聊天后撤销。':'当前助手缺少演出接口，仅阅读已有正文与标注。';
    for(const key of ['CHAT_CHANGED','MESSAGE_RECEIVED','MESSAGE_UPDATED','MESSAGE_DELETED','MESSAGE_SWIPED','GENERATION_STARTED','GENERATION_ENDED','GENERATION_STOPPED']){
      const names=new Set([events[key],helperEvents[key]].filter(Boolean));
      for(const name of names)listen(name,()=>{
        if(dead)return;
        if(key==='CHAT_CHANGED'){
          const next=chatKey(context());
           
          if(next!==chatIdentity)changeChat(next);
          else if(typeof next!=='string'){changeChat(null);sessions.clear();changeChat(next);}
          queue();return;
        }
        if(key==='GENERATION_STARTED'){generationByEvent=true;generating=true;stopAuto();$('form button').disabled=true;$('.history select').disabled=true;}
        if(key==='GENERATION_ENDED'||key==='GENERATION_STOPPED'){generationByEvent=false;injection.clear();}
        queue();
      });
    }
  }
  for(const name of ['pagehide','unload']){local.addEventListener(name,destroy,{once:true});disposers.push(()=>local.removeEventListener(name,destroy));}
   
  const ob=new host.MutationObserver(()=>{if(dead)return;if(owner&&!owner.isConnected){destroy();return;}if(doc.querySelector('#chat')!==observedChat||doc.querySelector('#mes_stop')!==observedStop){bindObservers();queue();}isolateHost();});
  ob.observe(doc.documentElement,{childList:true,subtree:true});disposers.push(()=>ob.disconnect());
